import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import './AttendancePage.css';
import axios from 'axios';
import moment from 'moment';

const createMockTimeLogs = (employees) => {
    // Ensure we don't crash if employees is not an array
    if (!Array.isArray(employees)) return [];

    const logs = [];
    employees.forEach(employee => {
        for (let day = 1; day <= 28; day++) {
            const statusOptions = ['Present', 'Absent', 'On Leave', 'Half Day', 'Present'];
            const status = statusOptions[Math.floor(Math.random() * statusOptions.length)];

            logs.push({
                id: `${employee.id}-${day}`,
                employee: employee,
                date: `2025-10-${String(day).padStart(2, '0')}`,
                clockIn: (status === 'Present' || status === 'Half Day') ? `09:${String(day % 15).padStart(2, '0')} AM` : '--:--',
                clockOut: status === 'Present' ? `05:${String(day * 2).padStart(2, '0')} PM` : (status === 'Half Day' ? '01:00 PM' : '--:--'),
                status,
            });
        }
    });
    return logs;
};

// --- DailyLogTable helper component (defined outside) ---
const DailyLogTable = ({ logs, isLoading }) => {
    if (isLoading) return <div className="text-center py-8 text-subtext-light bg-card-light rounded-lg">Loading...</div>;
    if (!logs || logs.length === 0) return <div className="text-center py-8 text-subtext-light bg-card-light rounded-lg">No records found for this day.</div>;

    return (
        <div className="bg-card-light dark:bg-card-dark rounded-xl shadow-sm overflow-x-auto">
            <table className="w-full text-sm text-left">
                <thead className="text-xs uppercase bg-background-light">
                    <tr>
                        <th className="px-6 py-3">Employee</th>
                        <th className="px-6 py-3">Clock In</th>
                        <th className="px-6 py-3">Clock Out</th>
                        <th className="px-6 py-3">Status</th>
                    </tr>
                </thead>
                <tbody>
                    {logs.map(log => (
                        <tr key={log.id} className="border-b">
                            <td className="px-6 py-4 font-medium">{log.employee.firstName} {log.employee.lastName}</td>
                            <td className="px-6 py-4">{log.clockIn}</td>
                            <td className="px-6 py-4">{log.clockOut}</td>
                            <td className="px-6 py-4">
                               <span className={`px-2 py-1 text-xs font-semibold rounded-full day-${log.status.toLowerCase().replace(' ', '-')}`}>{log.status}</span>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};


const AttendancePage = () => {
  // 1. ALWAYS INITIALIZE ARRAY STATE WITH AN EMPTY ARRAY []
  const [allEmployees, setAllEmployees] = useState([]);
  const [allTimeLogs, setAllTimeLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const [departmentFilter, setDepartmentFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  const [selectedDate, setSelectedDate] = useState(new Date());

  useEffect(() => {
    const fetchAndPrepareData = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setAllEmployees(employeesData);

        if (employeesData.length > 0) {
            setAllTimeLogs(createMockTimeLogs(employeesData));
        }
      } catch (error) {
        console.error("Failed to fetch employees:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAndPrepareData();
  }, []);

  const employeesToDisplay = allEmployees
    .filter(emp => departmentFilter === 'All' || emp.department === departmentFilter)
    .filter(emp => 
      `${emp.firstName} ${emp.lastName}`.toLowerCase().includes(searchQuery.toLowerCase())
    );

  const departments = [...new Set(allEmployees.map(emp => emp.department))];

  // 2. ADD A GUARD CLAUSE: Don't try to filter if allTimeLogs is not ready
  const dailyLogs = !isLoading && allTimeLogs.length > 0 ? allTimeLogs.filter(log => 
    moment(log.date).isSame(selectedDate, 'day') &&
    employeesToDisplay.some(emp => emp.id === log.employee.id)
  ) : [];

  const tileClassName = ({ date, view }) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6">
        <div>
          <h1 className="text-3xl font-bold">Attendance Calendar</h1>
          <p className="text-sm text-subtext-light">Filter by department or search for an employee.</p>
        </div>
        <div className="flex items-center gap-4 w-full md:w-auto">
          <select 
            value={departmentFilter}
            onChange={(e) => setDepartmentFilter(e.target.value)}
            className="w-full md:w-48"
          >
            <option value="All">All Departments</option>
            {departments.map(dept => <option key={dept} value={dept}>{dept}</option>)}
          </select>

          <div className="relative w-full md:w-64">
            <span className="material-icons absolute left-3 top-1/2 -translate-y-1/2 text-subtext-light">search</span>
            <input 
              type="text"
              placeholder="Search by name..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10"
            />
          </div>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
        <Calendar
          onChange={setSelectedDate}
          value={selectedDate}
          tileClassName={tileClassName}
          className="w-full border-none"
        />
      </div>

      <div className="mt-8">
        <h3 className="text-xl font-semibold mb-4">
          Logs for {moment(selectedDate).format('MMMM Do, YYYY')}
        </h3>
        <DailyLogTable logs={dailyLogs} isLoading={isLoading} />
      </div>
    </div>
  );
};

export default AttendancePage;
